INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('nationalfeiertag-2026-wien-angelobung-heldenplatz-programm','Nationalfeiertag 2026 in Wien: Angelobung am Heldenplatz und Programm','Kranzniederlegung um 10 Uhr, Angelobung von über 1.000 Rekruten ab 11 Uhr, offenes Kanzleramt am Nachmittag: die wichtigsten Termine zum Nationalfeiertag in Wien.','Der **Nationalfeiertag 2026** steht in Wien ganz im Zeichen von Staatsakt und offenen Türen: Am Montag, 26. Oktober, legen Regierungsmitglieder am Äußeren Burgtor einen Kranz nieder, am Heldenplatz werden mehr als 1.000 Rekrutinnen und Rekruten angelobt. Zugleich können Interessierte das Bundeskanzleramt am Ballhausplatz besichtigen. Ein Überblick über die wichtigsten Termine des Tages.

## Nationalfeiertag 2026: Kranzniederlegung am Äußeren Burgtor

Den offiziellen Auftakt bildet laut Terminvorschau des Bundespressedienstes eine Kranzniederlegung um 10 Uhr am Äußeren Burgtor. Daran nehmen Bundeskanzler Christian Stocker, weitere Mitglieder der Bundesregierung sowie die Staatssekretärinnen und Staatssekretäre teil. Auch die Präsidentschaftskanzlei führt die Kranzniederlegung im Weiheraum des Burgtors im Programm des Tages an, das am Heldenplatz ab 9.30 Uhr beginnt.

Zusätzlich tritt am Feiertag der Ministerrat im Bundeskanzleramt zusammen. Eine Uhrzeit wurde dafür nicht veröffentlicht, ein Pressefoyer im Anschluss ist diesmal nicht vorgesehen.

## Angelobung am Heldenplatz: Über 1.000 Rekruten

Ab 11 Uhr folgt der zentrale Programmpunkt: die Angelobung von Rekrutinnen und Rekruten des Bundesheeres am Heldenplatz. Nach Angaben des Verteidigungsministeriums sind es heuer mehr als 1.000 junge Menschen, die nach vier Wochen Grundausbildung ihr Treuegelöbnis auf die Republik ablegen. Dabei sind Bundespräsident Alexander Van der Bellen und die Bundesregierung anwesend.

Die Rede des Bundeskanzlers am Heldenplatz wird auf der Facebook-Seite des Bundeskanzleramts live übertragen. Wer den Festakt im Fernsehen verfolgen möchte, kann ab 10.45 Uhr die „ZIB Spezial“ in ORF 2 einschalten, die von der Angelobung berichtet.

## Leistungsschau des Bundesheeres in der Innenstadt

Rund um die Angelobung präsentiert sich das Bundesheer bei seiner Informations- und Leistungsschau. Diese läuft seit 20. Oktober in der Wiener Innenstadt und erreicht am Nationalfeiertag ihren Höhepunkt. Auf dem Heldenplatz geht es um die militärische Landesverteidigung, vor dem Burgtheater stellt sich der Heeressport vor.

Besucherinnen und Besucher können Gerät aus der Nähe ansehen, sich über Berufe beim Heer informieren und eine virtuelle Erlebniswelt ausprobieren. Für ein Gewinnspiel sammelt man an sechs Stationen je einen Buchstaben für ein Lösungswort:

- Eurofighter
- Radpanzer Pandur mit dem Flugabwehrsystem Skyranger
- Virtuelle Erlebniswelt
- Sport beim Heer
- Klettern mit dem Jägerbataillon 24
- Pioniertaucher

Als Hauptpreis winkt eine Fahrt mit dem Heißluftballon „Polaris“ des Bundesheeres für zwei Personen. Verteidigungsministerin Klaudia Tanner betont, der Feiertag mache die Leistungsfähigkeit des Heeres für die Bevölkerung erlebbar.

## Tag der offenen Tür im Bundeskanzleramt

Am Nachmittag öffnet das Bundeskanzleramt am Ballhausplatz 2 im 1. Bezirk seine Türen. Von 12 bis 17 Uhr führt ein Rundgang durch die Repräsentationsräume des Hauses, der letzte Einlass ist um 16.30 Uhr. Wer mehrere Stationen verbinden will, kann den Besuch gut mit dem Parlament kombinieren, das ebenfalls einen Tag der offenen Tür anbietet.

Am Abend wendet sich der Bundespräsident traditionell mit einer TV-Ansprache zum Nationalfeiertag an die Bevölkerung. Der 26. Oktober erinnert an den Beschluss über die immerwährende Neutralität Österreichs im Jahr 1955 und ist gesetzlicher Feiertag.

## Tipps für den Besuch

Wer den Heldenplatz besuchen möchte, plant am besten etwas Zeit ein und reist öffentlich an, da die Innenstadt am Feiertag stark frequentiert ist. Aktuelle Informationen, Fotos und einen Livestream stellt das Bundesheer online bereit.','politik','Innenpolitik','wien','news','Presseinfo Redaktion','/assets/img/artikel/nationalfeiertag-2026-wien-angelobung-heldenplatz-programm.webp','Bundespressedienst (Bundeskanzleramt) via APA-OTS; Bundesheer','https://www.ots.at/presseaussendung/OTS_20261020_OTS0151/aviso-terminvorschau-zum-nationalfeiertag-2026','published','2026-10-26T08:50:00.000Z','2026-10-26T08:45:56.781Z','Nationalfeiertag 2026 Wien: Angelobung & Programm','Nationalfeiertag 2026 in Wien: Kranzniederlegung, Angelobung von über 1.000 Rekruten am Heldenplatz, offenes Kanzleramt. Alle Zeiten im Überblick.','Nationalfeiertag 2026','["Nationalfeiertag 2026","Nationalfeiertag Wien","Angelobung Heldenplatz","Leistungsschau Bundesheer","Tag der offenen Tür Bundeskanzleramt","Nationalfeiertag 2026 Programm Wien","Kranzniederlegung Burgtor","Rekruten Angelobung 2026"]','Nationalfeiertag 2026: Angelobung von Rekruten am Heldenplatz in Wien','Wide view of Heldenplatz in Vienna on an autumn morning, long rows of Austrian army recruits in uniform standing in formation seen from behind and far away, red-white-red flags, Hofburg palace facade in soft background, crowd of spectators, no text, no logos, no readable signs','[{"q":"Wann ist die Angelobung am Nationalfeiertag 2026?","a":"Die Angelobung der Rekrutinnen und Rekruten beginnt am 26. Oktober 2026 ab 11 Uhr am Wiener Heldenplatz, ORF 2 berichtet ab 10.45 Uhr."},{"q":"Kann man das Bundeskanzleramt am Nationalfeiertag besichtigen?","a":"Ja, von 12 bis 17 Uhr gibt es einen Rundgang durch die Repräsentationsräume am Ballhausplatz 2, letzter Einlass ist um 16.30 Uhr."},{"q":"Wo findet die Leistungsschau des Bundesheeres statt?","a":"Am Heldenplatz (Landesverteidigung) und vor dem Burgtheater (Heeressport) in der Wiener Innenstadt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
